"""Checks for private and public computed-field representation."""

from pydantic import BaseModel, computed_field


class _SessionView(BaseModel):
    """Small model used to compare public and private computed fields."""

    account: str

    @computed_field
    @property
    def display_name(self) -> str:
        """Return the public display form."""
        return self.account.upper()

    @computed_field
    @property
    def _access_token(self) -> str:
        return 'fixture-value'


def test_private_computed_property_is_not_exposed_by_model_repr():
    """Private computed values do not appear in the model representation."""
    view = _SessionView(account='reviewer')

    rendered = repr(view)
    assert "display_name='REVIEWER'" in rendered
    assert '_access_token' not in rendered
    assert 'fixture-value' not in rendered
    assert _SessionView.model_computed_fields['display_name'].repr is True
    assert _SessionView.model_computed_fields['_access_token'].repr is False
